import { World, emptyInput } from '../../src/game/simulation/world';

const snapshot = (world) => ({
  mode: world.mode,
  life: world.player.life,
  level: world.progression.level,
  position: { x: world.player.x, y: world.player.y },
  current: { col: world.currentWrapper.col, row: world.currentWrapper.row },
  transit: world.transit ? {
    age: world.transit.age,
    next: { col: world.transit.next.col, row: world.transit.next.row },
    target: { ...world.transit.target },
  } : null,
});

const cases = [];
for (const nearArrival of [false, true]) {
  const world = new World([], [], 1);
  world.jump({ x: 1, y: 0 });
  if (nearArrival) {
    world.player.x = world.transit.target.x;
    world.player.y = world.transit.target.y;
  }
  world.player.life = world.player.maxLife;
  const before = snapshot(world);
  world.step(emptyInput());
  const afterOpening = snapshot(world);
  const offer = world.offers[0];
  world.step(emptyInput());
  const nextFrame = snapshot(world);
  if (offer) world.selectUpgrade(offer);
  const afterChoice = snapshot(world);
  cases.push({ nearArrival, before, afterOpening, nextFrame, afterChoice });
}
console.log(JSON.stringify({
  scope: 'Isolated recreation simulation diagnostic with artificial full health and positioning. Not ordinary browser play, original-runtime observation, or a matched differential.',
  cases,
}, null, 2));

